const items = $input.all();
if (!items.length) return [];
const keys = Object.keys(items[0].json);
const findKey = (name) => keys.find(k => k.trim().toLowerCase() === name.toLowerCase());
const STATUS_KEY = findKey('status') || findKey('status ');
const KEYWORD_KEY = findKey('keywords');
const COMPANY_KEY = findKey('company');
const COMP_DESC_KEY = findKey('company_description');
const EXT_KEY = findKey('external links') || findKey('external_links');
const SIM_KEY = findKey('similar links') || findKey('similar_links');
const TOPIC_KEY = findKey('topic');
const LOGO_KEY = findKey('logo_url');
const MUSTARD_KEY = findKey('mustard_oil_url');
const GROUNDNUT_KEY = findKey('groundnut_oil_url');
const A2_GHEE_KEY = findKey('a2_bilona_cow_ghee_url');
const DESI_GHEE_KEY = findKey('desi_cow_ghee_url');
const WALNUTS_KEY = findKey('walnuts_url');
const ALMONDS_KEY = findKey('almonds_url');
const JAGGERY_KEY = findKey('jaggery_powder_url');
if (!STATUS_KEY || !KEYWORD_KEY) throw new Error('Status or Keywords column not found. Keys: ' + keys.join(', '));
const clean = (v) => String(v||'').trim();
const pending = items.filter(i => clean(i.json[STATUS_KEY]).toLowerCase() === 'pending');
if (!pending.length) return [];
const batch = pending.slice(0, 5);
const pkw = batch[0].json;
const allPairs = batch.map(row => ({
  keyword: clean(row.json[KEYWORD_KEY]),
  similarLink: clean(row.json[SIM_KEY])
}));
const pkwKeyword = allPairs[0].keyword;
const pkwLink = clean(pkw[EXT_KEY]) || allPairs[0].similarLink;
const skwPairs = allPairs.slice(1).filter(p => p.keyword);
const topic = clean(pkw[TOPIC_KEY]);
return [{ json: {
  primary_keyword: pkwKeyword,
  primary_link: pkwLink,
  secondary_keywords: skwPairs.map(p => p.keyword),
  skwLinkPairs: skwPairs,
  topic: topic,
  company: clean(pkw[COMPANY_KEY]),
  description: clean(pkw[COMP_DESC_KEY]),
  all_keywords: [pkwKeyword, ...skwPairs.map(p=>p.keyword)],
  logo_url: clean(pkw[LOGO_KEY]),
  mustard_oil_url: clean(pkw[MUSTARD_KEY]),
  groundnut_oil_url: clean(pkw[GROUNDNUT_KEY]),
  a2_bilona_cow_ghee_url: clean(pkw[A2_GHEE_KEY]),
  desi_cow_ghee_url: clean(pkw[DESI_GHEE_KEY]),
  walnuts_url: clean(pkw[WALNUTS_KEY]),
  almonds_url: clean(pkw[ALMONDS_KEY]),
  jaggery_powder_url: clean(pkw[JAGGERY_KEY])
}}];

const search1 = $items('Serper Search 1')[0]?.json || {};
const search2 = $items('Serper Search 2')[0]?.json || {};
const batchData = $items('Select Pending Batch')[0]?.json || {};
const extractContext = (results) => {
  return (results?.organic || []).slice(0, 5).map(r => ({
    title: String(r.title || '').trim(),
    snippet: String(r.snippet || '').trim()
  }));
};
const context1 = extractContext(search1);
const context2 = extractContext(search2);
const allContext = [...context1, ...context2];
const contextText = allContext.map((r, i) =>
  `Result ${i+1}:
Title: ${r.title}
Snippet: ${r.snippet}`
).join('

');
const prompt = `You are an SEO content strategist. Based on the search results below, generate exactly 2 strong H2 section headings for a blog post.

BLOG TOPIC: ${batchData.topic}
PRIMARY KEYWORD: ${batchData.primary_keyword}
SECONDARY KEYWORDS: ${(batchData.secondary_keywords||[]).join(', ')}

SEARCH RESULTS FROM GOOGLE:
${contextText}

RULES FOR H2 HEADINGS:
- Must be specific and descriptive (not generic)
- Must naturally include the primary keyword or a secondary keyword
- Must represent a real section of content (not a page title)
- NO brand names (no Healthline, WebMD, Amazon, Patanjali, Delight Farms etc)
- NO numbers like "8 Benefits" at the start
- Each heading 6-12 words long
- Should cover different aspects of the topic
- Think like: what are the 2 most important things readers want to know?

Respond ONLY in JSON:
{
  "h2_hints": ["First H2 heading here", "Second H2 heading here"]
}`;
return [{ json: { ...batchData, h2_generation_prompt: prompt } }];

const item = $input.first().json;
const batchData = $items('Prepare Search Context')[0]?.json || {};
let h2Hints = [];
try {
  let raw = String(item.output || item.text || '');
  raw = raw.replace(/```json/gi,'').replace(/```/g,'').trim();
  const match = raw.match(/\{[\s\S]*\}/);
  if (match) {
    const parsed = JSON.parse(match[0]);
    h2Hints = parsed.h2_hints || [];
  }
} catch(e) { h2Hints = []; }
if (h2Hints.length === 0) h2Hints.push('Health Benefits of ' + batchData.primary_keyword.charAt(0).toUpperCase() + batchData.primary_keyword.slice(1));
if (h2Hints.length === 1) h2Hints.push('How to Use ' + batchData.primary_keyword.charAt(0).toUpperCase() + batchData.primary_keyword.slice(1) + ' Every Day');
return [{ json: { ...batchData, h2Hints } }];

const item = $input.first().json;
const batchData = $items('Parse H2 Hints')[0]?.json || {};
const extractQuestions = (data) => {
  const questions = [];
  try {
    const qs = data?.questions || data?.data?.questions || {};
    const preps = data?.prepositions || data?.data?.prepositions || {};
    const wh = ['who','what','where','how','why','when','which','will','can','are','is'];
    for (const w of wh) { const arr = qs[w] || []; if (Array.isArray(arr)) arr.slice(0,2).forEach(q => { if(q && String(q).length > 15) questions.push(String(q).trim()); }); }
    const prepWords = ['for','with','without','near','to','can','vs'];
    for (const p of prepWords) { const arr = preps[p] || []; if (Array.isArray(arr)) arr.slice(0,1).forEach(q => { if(q && String(q).length > 15) questions.push(String(q).trim()); }); }
    if (!questions.length) { const flat = data?.questions || data?.data || []; if (Array.isArray(flat)) flat.slice(0,10).forEach(q => { const txt = q?.query || q?.question || q?.text || String(q); if (txt && txt.length > 15) questions.push(txt.trim()); }); }
  } catch(e) {}
  return [...new Set(questions.filter(Boolean))].slice(0, 10);
};
return [{ json: { ...batchData, faqs: extractQuestions(item) } }];

