const item = $input.first().json;
let outline = {};
try {
  let raw = String(item.output || item.text || '');
  raw = raw.replace(/```json/gi,'').replace(/```/g,'').trim();
  const match = raw.match(/\{[\s\S]*\}/);
  if (match) outline = JSON.parse(match[0]);
} catch(e) { outline = {}; }
const rd = $items('Parse Research Output')[0]?.json || {};
const makeSlug = (s) => String(s).toLowerCase().replace(/[^a-z0-9\s-]/g,'').trim().replace(/\s+/g,'-').slice(0,70);
const sections = outline.sections || [];
const h2s = sections.map(s => s.h2).filter(Boolean);
const now = new Date();
const publishDate = now.toLocaleString('en-US', { month: 'long', year: 'numeric' });
const readTime = Math.max(6, Math.round(((h2s.length * 300) + 800) / 200));

// Build TOC with H3 sub-items
const tocItems = [];
sections.forEach((s, i) => {
  const h2Num = (i + 1);
  tocItems.push('<li><a href="#' + makeSlug(s.h2) + '">' + s.h2 + '</a>');
  if (s.h3s && s.h3s.length) {
    tocItems.push('<ol class="toc-sub">');
    s.h3s.forEach((h3, j) => {
      const h3Num = h2Num + '.' + (j + 1);
      tocItems.push('<li><span class="toc-num">' + h3Num + '</span><a href="#' + makeSlug(h3) + '">' + h3 + '</a></li>');
    });
    tocItems.push('</ol>');
  }
  tocItems.push('</li>');
});

const tocHtml = '<nav class="toc" role="navigation">\n<h2>Table of Contents</h2>\n<ol>\n' +
  tocItems.join('\n') +
  '\n<li><a href="#faq">Frequently Asked Questions</a></li>\n</ol>\n</nav>';

return [{ json: {
  ...rd,
  outline, h2s, sections, tocHtml, publishDate, readTime,
  h1_title: outline.h1_title || rd.primary_keyword,
  featured_tagline: outline.featured_tagline || 'Pure Natural Traditional',
  key_takeaways: outline.key_takeaways || [],
  conclusion_angle: outline.conclusion_angle || '',
  blog_conclusion: outline.blog_conclusion || ''
}}];

