// ── Extract FAQ Q&A pairs from <details> tags in HTML ──
const faqPairs = [];
const detailsRegex = /<details[\s\S]*?<summary[^>]*>([\s\S]*?)<\/summary>[\s\S]*?<p>([\s\S]*?)<\/p>[\s\S]*?<\/details>/gi;
let fm;
while ((fm = detailsRegex.exec(bodyHtml)) !== null && faqPairs.length < 10) {
  const question = fm[1].replace(/<[^>]*>/g, '').trim();
  const answer = fm[2].replace(/<[^>]*>/g, '').trim();
  if (question) faqPairs.push({ question, answer });
}

if (faqPairs.length === 0) {
  const rawFaqs = d.faqs || [];
  rawFaqs.slice(0, 10).forEach(q => {
    const question = safeStr(typeof q === 'string' ? q : q.question || q.q || '');
    const answer = safeStr(typeof q === 'object' ? q.answer || q.a || '' : '');
    if (question) faqPairs.push({ question, answer });
  });
}

